CREATE TABLE users (id SERIAL PRIMARY KEY, nama VARCHAR(100) NOT NULL, email VARCHAR(100) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, telepon VARCHAR(20), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE vehicles (id SERIAL PRIMARY KEY, user_id INT NOT NULL REFERENCES users(id), plat VARCHAR(15) NOT NULL, merk VARCHAR(50), jenis VARCHAR(10) NOT NULL CHECK (jenis IN ('motor','mobil','truk')));
CREATE TABLE drivers (id SERIAL PRIMARY KEY, nama VARCHAR(100) NOT NULL, telepon VARCHAR(20), plat_towing VARCHAR(15), online BOOLEAN DEFAULT TRUE, lat DECIMAL(10,7), lng DECIMAL(10,7));
CREATE TABLE orders (id SERIAL PRIMARY KEY, user_id INT NOT NULL REFERENCES users(id), driver_id INT REFERENCES drivers(id), vehicle_id INT REFERENCES vehicles(id), jemput_lat DECIMAL(10,7), jemput_lng DECIMAL(10,7), jemput_alamat VARCHAR(255), tujuan_lat DECIMAL(10,7), tujuan_lng DECIMAL(10,7), tujuan_alamat VARCHAR(255), jarak_km DECIMAL(6,2), biaya INT, status VARCHAR(20) DEFAULT 'menunggu' CHECK (status IN ('menunggu','diterima','menuju_lokasi','dalam_perjalanan','selesai','dibatalkan')), metode_bayar VARCHAR(20), status_bayar VARCHAR(20) DEFAULT 'belum_bayar', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE reviews (id SERIAL PRIMARY KEY, order_id INT NOT NULL REFERENCES orders(id), rating SMALLINT CHECK (rating BETWEEN 1 AND 5), komentar TEXT);
